INSERT INTO user_tenant_selection (phone, id_company, updated_at)
VALUES ($1, $2, CURRENT_TIMESTAMP)
ON CONFLICT (phone) DO UPDATE SET id_company = EXCLUDED.id_company, updated_at = CURRENT_TIMESTAMP;

INSERT INTO pending_user_query (phone, query_text, created_at)
VALUES ($1, $2, CURRENT_TIMESTAMP)
ON CONFLICT (phone) DO UPDATE SET query_text = EXCLUDED.query_text, created_at = CURRENT_TIMESTAMP;

DELETE FROM pending_user_query
WHERE phone = $1
RETURNING query_text;

